<template><ContentWrap><el-form inline><el-select v-model="scope" clearable placeholder="Scope"><el-option v-for="x in ['MEMBER','MEMBER_ROBOT','ROBOT']" :key="x" :value="x"/></el-select><el-input v-model="type" placeholder="Memory Type" clearable/><el-input v-model="member" placeholder="成员 ID/名称" clearable/><el-input v-model="robot" placeholder="机器人 ID/名称" clearable/><el-select v-model="status" clearable placeholder="状态"><el-option value="ACTIVE"/><el-option value="SUPERSEDED"/><el-option value="DELETED"/></el-select></el-form><el-table :data="filtered"><el-table-column prop="scope" label="范围"/><el-table-column label="成员"><template #default="{row}">{{row.memberName||row.memberId||'-'}}</template></el-table-column><el-table-column label="机器人"><template #default="{row}">{{row.robotName||row.robotId||'-'}}</template></el-table-column><el-table-column prop="memoryType" label="类型"/><el-table-column prop="content" label="内容"/><el-table-column prop="importance" label="重要度"/><el-table-column prop="expiresAt" label="过期时间"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">失效</el-button></template></el-table-column></el-table><el-dialog v-model="open" title="编辑长期记忆"><el-input v-model="form.content" type="textarea"/><el-input v-model="form.summary" placeholder="摘要"/><el-input-number v-model="form.importance" :min="0" :max="1" :step=".05"/><el-date-picker v-model="form.expiresAt" type="datetime"/><template #footer><el-button type="primary" @click="save">保存</el-button></template></el-dialog></ContentWrap></template><script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{AiMemoryApi,type MemoryVO}from'@/api/ai/memory';const rows=ref<MemoryVO[]>([]),scope=ref(''),type=ref(''),member=ref(''),robot=ref(''),status=ref(''),open=ref(false),form=reactive<any>({});const filtered=computed(()=>rows.value.filter(x=>(!scope.value||x.scope===scope.value)&&(!type.value||x.memoryType.includes(type.value))&&(!status.value||x.status===status.value)&&(!member.value||String(x.memberId||'').includes(member.value))&&(!robot.value||String(x.robotId||'').includes(robot.value))));async function load(){rows.value=await AiMemoryApi.list()}function edit(r:MemoryVO){Object.assign(form,r);open.value=true}async function save(){await AiMemoryApi.update(form.id,{content:form.content,summary:form.summary,importance:form.importance,expiresAt:form.expiresAt});open.value=false;await load()}async function remove(r:MemoryVO){await AiMemoryApi.delete(r.id);await load()}onMounted(load)</script>